window.sleep = (ms) => new Promise((r) => setTimeout(r, ms));
window.until = async (fn, ms = 10000) => { const t0 = Date.now(); while (Date.now() - t0 < ms) { if (fn()) return true; await sleep(150) } return false };
window.nav = (name) => [...document.querySelectorAll('nav button')].find((b) => b.textContent.trim() === name).click();
window.setInput = (input, value) => { const set = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value').set; set.call(input, value); input.dispatchEvent(new Event('input', { bubbles: true })); input.dispatchEvent(new Event('change', { bubbles: true })) };
window.chooseSelect = async (title, value) => { const el = [...document.querySelectorAll('select')].find((x) => x.title === title); if (!el) return 'NO SELECT ' + title; Object.getOwnPropertyDescriptor(HTMLSelectElement.prototype, 'value').set.call(el, String(value)); el.dispatchEvent(new Event('change', { bubbles: true })); await sleep(900); return title + ' = ' + (el.selectedOptions[0]?.textContent ?? el.value) };
window.rail = (code) => { const b = [...document.querySelectorAll('[aria-label="The day’s games"] button')].find((x) => x.textContent.includes(code)); if (!b) return 'NOT ON THE RAIL ' + code; b.click(); return 'opened ' + b.innerText.replace(/\n/g, ' ') };
window.cells = (r) => [...r.querySelectorAll('[role=cell]')].map((c) => c.textContent.trim());
window.pairs = () => { const s = document.querySelector('section[aria-label="Who guarded whom"]'); if (!s) return 'NO SECTION'; const tables = [...s.querySelectorAll('[role=table]')]; return { text: s.innerText.split('\n').slice(0, 3).join(' | '), counts: [...s.querySelectorAll('.font-semibold + span')].map((e) => e.textContent), sides: tables.map((t) => ({ side: t.getAttribute('aria-label'), rows: t.querySelectorAll('[role=row]').length - 1, first: cells([...t.querySelectorAll('[role=row]')][1] ?? t) })) } };
window.officials = () => document.querySelector('[aria-label=Officials]')?.innerText ?? 'NO OFFICIALS LINE';
window.clickText = async (text) => { const b = [...document.querySelectorAll('button')].find((x) => x.textContent.trim() === text); if (!b) return 'NO BUTTON ' + text; b.click(); await sleep(1200); return 'clicked ' + text };
window.officialTable = (label, n = 3, last = false) => { const t = document.querySelector('[role=table][aria-label="' + label + '"]'); if (!t) return 'NO TABLE ' + label; const rows = [...t.querySelectorAll('[role=row]')]; return { head: [...rows[0].children].map((c) => c.textContent), seasons: rows.length - 1, rows: (last ? rows.slice(-n) : rows.slice(1, 1 + n)).map(cells) } };
window.findRow = (label, name) => { const t = document.querySelector('[role=table][aria-label="' + label + '"]'); const r = t && [...t.querySelectorAll('[role=row]')].find((x) => x.textContent.startsWith(name)); return r ? cells(r) : 'NO ROW ' + name };
window.openPlayer = async (name) => { const input = document.querySelector('input[aria-label="Search players"]'); const set = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value').set; set.call(input, name); input.dispatchEvent(new Event('input', { bubbles: true })); await until(() => [...document.querySelectorAll('aside button')].some((x) => x.textContent.includes(name))); const b = [...document.querySelectorAll('aside button')].find((x) => x.textContent.includes(name)); if (!b) return 'NOT LISTED'; b.click(); await until(() => document.querySelector('h1')?.innerText.replace(/\n/g, ' ').includes(name.split(' ').pop())); return 'opened ' + document.querySelector('h1')?.innerText.replace(/\n/g, ' ') };
window.tab = async (label) => { const t = [...document.querySelectorAll('[role=tab]')].find((x) => x.textContent.trim() === label); if (!t) return 'NO TAB ' + label; t.click(); await sleep(1200); return 'tab ' + label };
window.M = (id) => document.querySelector('[data-metric=' + id + ']')?.innerText.replace(/\n/g, ' | ') ?? 'MISSING ' + id;
window.pairTable = (title) => { const t = document.querySelector('[role=table][aria-label="' + title + '"]'); if (!t) return 'NO TABLE ' + title; const rows = [...t.querySelectorAll('[role=row]')].slice(1); return { rows: rows.length, first: rows.slice(0, 2).map(cells) } };
